// AUDITOR DE LEYES FÍSICAS SENTINEL
// Reemplaza a LLM pesado por lógica determinista para ahorrar GPU.

const data = $input.all()[0].json.body.data;
const coherence = data.physics ? data.physics.coherence : 0;
const friction = data.physics ? data.physics.friction : 0;
const harvest = data.harvest || 0;

let verified = true;
let reason = "Operación nominal dentro de parámetros físicos.";

// 1. Ley de Coherencia Mínima
// El sistema no puede cosechar eficientemente si está desfasado
if (coherence < 0.6 && harvest > 0.5) {
  verified = false;
  reason = "VIOLACIÓN: Cosecha alta detectada sin coherencia de fase suficiente.";
}

// 2. Ley de Fricción Térmica
// Si la fricción es alta (CPU load alto), la eficiencia DEBE bajar.
// Si reporta 100% eficiencia con alta fricción, es un dato falso.
if (friction > 0.4 && harvest > 0.8) {
  verified = false;
  reason = "VIOLACIÓN: Eficiencia imposible bajo condiciones de alta fricción térmica.";
}

// 3. Integridad de Datos
if (harvest < 0) {
  verified = false;
  reason = "ERROR: Cosecha negativa (Imposible físico).";
}

return {
  verified: verified,
  reason: reason,
  physics_check: {
    coherence_ok: coherence >= 0.6,
    friction_ok: friction <= 0.4
  }
};
